import csv,pandas as pd,numpy as np
from collections import defaultdict
from scipy.optimize import linear_sum_assignment
obs=pd.read_csv('ref_obs.tsv',sep='\\t',index_col=0); tmap=obs[['guide','target_gene']].drop_duplicates().set_index('guide')['target_gene'].to_dict()
def read(path):
 d=defaultdict(list)
 with open(path) as f:
  r=csv.DictReader(f,delimiter='\\t')
  for row in r:
   cl=row['cluster']
   if cl.startswith('NT-'): continue
   d[cl].append((row['genes'],float(row['scores']),float(row['logfoldchanges']),int(row['rank'])))
 return d
R=read('ref_findmarkers.tsv'); Q=read('query_findmarkers_x.tsv')
ref=sorted(R); qry=sorted(Q,key=lambda x:int(x[5:]))

def sim_sets(a,b,n=200,col='score',mode='signed'):
 # Since ranked by abs, choose strongest positive and negative separately from all rows.
 if col=='score': idx=1
 else: idx=2
 apos={g for g,s,l,r in sorted(a,key=lambda x:x[idx], reverse=True)[:n]}
 aneg={g for g,s,l,r in sorted(a,key=lambda x:x[idx])[:n]}
 bpos={g for g,s,l,r in sorted(b,key=lambda x:x[idx], reverse=True)[:n]}
 bneg={g for g,s,l,r in sorted(b,key=lambda x:x[idx])[:n]}
 if mode=='signed': return len(apos&bpos)+len(aneg&bneg)-len(apos&bneg)-len(aneg&bpos)
 if mode=='same': return len(apos&bpos)+len(aneg&bneg)
 if mode=='any': return len((apos|aneg)&(bpos|bneg))

def report(C,name):
 rows,cols=linear_sum_assignment(-C); inv={ref[j]:qry[i] for i,j in zip(rows,cols)}; miss=[ref[j] for j in set(range(len(ref)))-set(cols)]
 print('\\n',name,'missing',miss)
 for target in ['PABPC1','NUDT21','LEO1']:
  rg=[g for g in ref if tmap[g]==target][0]; j=ref.index(rg)
  print(target,rg,'assign',inv.get(rg),'top',[(qry[i],C[i,j]) for i in np.argsort(C[:,j])[::-1][:8]])
for col in ['score','lfc']:
 for mode in ['signed','same','any']:
  for n in [50,100,200,500,1000]:
   C=np.array([[sim_sets(R[rg],Q[qg],n,col,mode) for rg in ref] for qg in qry],float)
   report(C,f'{col}_{mode}_{n}')
